    def prune(tree_edges, terminals):
        """Iteratively drop edges to leaves that are not destinations."""
        edges = set(tree_edges)
        changed = True
        while changed:
            changed = False
            out_deg = {}
            in_deg = {}
            for s, t in edges:
                out_deg[s] = out_deg.get(s, 0) + 1
                in_deg[t] = in_deg.get(t, 0) + 1
            for s in list(out_deg):
